log.info({ orderId, totalCents }, "order placed");
log.error({ err, orderId }, "payment capture failed");

// tracing.ts - load before the app: node --import ./tracing.js server.js
import { NodeSDK } from "@opentelemetry/sdk-node";
import { getNodeAutoInstrumentations } from "@opentelemetry/auto-instrumentations-node";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";

const sdk = new NodeSDK({
  serviceName: "orders-api",
  traceExporter: new OTLPTraceExporter({ url: "http://otel-collector:4318/v1/traces" }),
  instrumentations: [getNodeAutoInstrumentations()],
});
sdk.start();

// manual span around business logic
import { trace } from "@opentelemetry/api";
const tracer = trace.getTracer("orders");
await tracer.startActiveSpan("chargeCard", async (span) => {
  span.setAttribute("order.id", orderId);
  try { await payments.charge(orderId); }
  catch (e) { span.recordException(e as Error); throw e; }
  finally { span.end(); }
});
